Server Component (async function, use client 없음). Next.js 16 App Router 기준 params는 Promise<{slug: string}>.

pseudocode:
export const revalidate = 60

export async function generateStaticParams() {
  const posts = await fetchPublishedPosts()
  return posts.map(p => ({ slug: p.slug }))
}

export default async function BlogPostPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params
  const post = await fetchPostBySlug(slug)
  if (!post) notFound()

  const blocks = await fetchPageBlocks(post.id)

  return (
    <article className='max-w-3xl mx-auto px-6 py-12'>
      <Button variant='ghost' size='sm' asChild className='mb-6 -ml-2'>
        <Link href='/blog'><ArrowLeft className='h-4 w-4 mr-1' />블로그 목록</Link>
      </Button>

      <header className='mb-8'>
        <CategoryBadge category={post.category} className='mb-3' />
        <h1 className='text-3xl font-bold mb-3'>{post.title}</h1>
        <div className='flex items-center gap-3 flex-wrap'>
          <TagBadge tags={post.tags} />
          <time dateTime={post.publishedAt} className='text-sm text-muted-foreground'>
            {format(parseISO(post.publishedAt), 'yyyy. MM. dd.', { locale: ko })}
          </time>
        </div>
      </header>

      <Separator className='mb-8' />

      <NotionRenderer blocks={blocks} />
    </article>
  )
}

Next.js 16에서 params는 반드시 await 필요 (Promise<{slug}>).
